var allLabels = $input.all().map(function(item) { return item.json; });
var emailData = $('Gmail Trigger').item.json;
var emailLabelIds = emailData.labelIds || [];

var isClienti = allLabels.some(function(label) {
  return emailLabelIds.includes(label.id) &&
    label.name &&
    label.name.toUpperCase().startsWith('CLIENTI');
});

var isPromotional = emailLabelIds.some(function(id) {
  return ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL'].includes(id);
});

return [{
  json: {
    isClientiEmail: isClienti,
    isPromotional: isPromotional,
    id: emailData.id || '',
    threadId: emailData.threadId || '',
    from: emailData.from || '',
    to: emailData.to || '',
    subject: emailData.subject || '',
    snippet: emailData.snippet || '',
    text: emailData.text || '',
    html: emailData.html || '',
    date: emailData.date || '',
    labelIds: emailData.labelIds || []
  }
}];

var items = $input.all();
var rawText = items.length > 0 ? (items[0].json.text || '') : '';
var topic = 'GENERALE';
var driveQuery = '';
try {
  var cleaned = rawText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  var m = cleaned.match(/\{[\s\S]*\}/);
  if (m) {
    var parsed = JSON.parse(m[0]);
    topic = parsed.topic || 'GENERALE';
    if (parsed.keywords && parsed.keywords.length > 0) {
      driveQuery = parsed.keywords.map(function(k) {
        return "fullText contains '" + String(k).replace(/'/g, "\\'") + "'";
      }).join(' OR ');
    }
  }
} catch (e) {}
var topicMap = { PAGHE: 'CONSULENTE DEL LAVORO E DELLA PREVIDENZA CLIENTI', DIRITTO_LAVORO: 'DIRITTO DEL LAVORO', PREVIDENZA: 'DIRITTO DELLA PREVIDENZA', INPS: 'INPS', INAIL: 'INAIL', AGGIORNAMENTI: 'AGGIORNAMENTI NORMATIVI', FISCALE_NORMATIVA: 'CONSULENZA FISCALE NORMATIVA', FISCALE_USPPIDA: 'CONSULENZA FISCALE USPPIDA', GENERALE: 'CONSULENTE DEL LAVORO E DELLA PREVIDENZA' };
var driveFolder = topicMap[topic] || topicMap.GENERALE;
if (!driveQuery) { driveQuery = driveFolder; }
return [{ json: { topic: topic, driveFolder: driveFolder, driveQuery: driveQuery } }];

var emailData = $('Gmail Trigger').item.json || {};
var topic = 'GENERALE';
try { topic = $('Mappa Argomento a Cartella').item.json.topic || 'GENERALE'; } catch(e) {}

var driveItems = [];
try { driveItems = $('Cerca Documenti Drive').all(); } catch(e) {}

var aggiornamenti = '';
try {
  var normItems = $input.all();
  if (normItems.length > 0) aggiornamenti = normItems[0].json.aggiornamenti || '';
} catch(e) {}

var driveContext = 'Nessun documento trovato su Google Drive per questa richiesta.';
var validItems = driveItems.filter(function(i) { return i.json && i.json.id; });
if (validItems.length > 0) {
  var lines = validItems.map(function(item, idx) {
    var name = item.json.name || ('Documento ' + (idx + 1));
    var link = item.json.webViewLink ? (' - ' + item.json.webViewLink) : '';
    return (idx + 1) + '. ' + name + link;
  });
  driveContext = 'Documenti trovati (argomento: ' + topic + '):\n' + lines.join('\n');
}

return [{ json: {
  from: String(emailData.from || ''),
  to: String(emailData.to || ''),
  subject: String(emailData.subject || ''),
  snippet: String(emailData.snippet || ''),
  text: String(emailData.text || ''),
  threadId: String(emailData.threadId || ''),
  id: String(emailData.id || ''),
  driveContext: driveContext,
  topic: topic,
  aggiornamenti: aggiornamenti
} }];

var items = $input.all();
var aiResponse = items.length > 0 ? (items[0].json.text || '') : '';
var emailData = $('Gmail Trigger').item.json || {};
return [{ json: {
  aiResponse: String(aiResponse),
  from: String(emailData.from || ''),
  subject: String(emailData.subject || ''),
  threadId: String(emailData.threadId || ''),
  messageId: String(emailData.id || '')
} }];

